import { UISession } from './UISession'
import type { Logger } from '@servicenow/sdk-build-core'

export async function getUISessionToken(
    creds: { instanceUrl: string; username: string; password: string },
    logger?: Logger
) {
    const { username, password, instanceUrl } = creds
    const session = new UISession(instanceUrl, logger)
    try {
        // verify basic auth credentials and get user token
        return session.login(username, password)
    } catch (error) {
        logger?.error(`Login to instance ${instanceUrl} failed: ${(error as Error).message}`)
        return
    }
}
